class TokenBucket {
  constructor(capacity, refillRatePerSecond) {
    this.capacity = capacity;
    this.refillRate = refillRatePerSecond;
    this.tokens = capacity;
    this.lastRefill = Date.now();
    this.lock = Promise.resolve();
  }

  async tryConsume() {
    // Serialize access with a simple promise chained lock, so only one
    // caller at a time can read and mutate tokens and lastRefill.
    const run = this.lock.then(() => {
      const now = Date.now();
      const elapsedSeconds = (now - this.lastRefill) / 1000;
      const refreshed = Math.min(
        this.capacity,
        this.tokens + elapsedSeconds * this.refillRate
      );
      this.lastRefill = now;

      if (refreshed >= 1) {
        this.tokens = refreshed - 1;
        return true;
      }
      this.tokens = refreshed;
      return false;
    });
    this.lock = run.catch(() => {});
    return run;
  }
}

module.exports = { TokenBucket };

