class LeakyBucket {
  constructor(capacity, leakRatePerSecond) {
    this.capacity = capacity;
    this.leakRate = leakRatePerSecond;
    this.queueSize = 0;
    this.lastLeak = Date.now();
    this.lock = Promise.resolve();
  }

  async tryAdd() {
    const run = this.lock.then(() => {
      const now = Date.now();
      const elapsedSeconds = (now - this.lastLeak) / 1000;
      const leaked = elapsedSeconds * this.leakRate;
      this.queueSize = Math.max(0, this.queueSize - leaked);
      this.lastLeak = now;

      if (this.queueSize < this.capacity) {
        this.queueSize += 1;
        return true;
      }
      return false;
    });
    this.lock = run.catch(() => {});
    return run;
  }
}

