class ApiRateLimiter {
  constructor(capacity, refillRatePerSecond) {
    this.capacity = capacity;
    this.refillRate = refillRatePerSecond;
    this.buckets = new Map(); // clientId -> { tokens, lastRefill, lock }
  }

  getOrCreateBucket(clientId) {
    if (!this.buckets.has(clientId)) {
      this.buckets.set(clientId, {
        tokens: this.capacity,
        lastRefill: Date.now(),
        lock: Promise.resolve(),
      });
    }
    return this.buckets.get(clientId);
  }

  async allow(clientId) {
    const bucket = this.getOrCreateBucket(clientId);
    const run = bucket.lock.then(() => {
      const now = Date.now();
      const elapsedSeconds = (now - bucket.lastRefill) / 1000;
      const refreshed = Math.min(
        this.capacity,
        bucket.tokens + elapsedSeconds * this.refillRate
      );
      bucket.lastRefill = now;

      if (refreshed >= 1) {
        bucket.tokens = refreshed - 1;
        return true;
      }
      bucket.tokens = refreshed;
      return false;
    });
    bucket.lock = run.catch(() => {});
    return run;
  }
}

async function handleRequest(limiter, clientId, requestId) {
  const allowed = await limiter.allow(clientId);
  if (!allowed) {
    console.log(`request ${requestId} for ${clientId}: rejected, too many requests`);
