import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

public class ApiRateLimiter {
    private static class Bucket {
        double tokens;
        long lastRefillNanos;
        final ReentrantLock lock = new ReentrantLock();
    }

    private final double capacity;
    private final double refillRatePerSecond;
    private final Map<String, Bucket> buckets = new ConcurrentHashMap<>();

    public ApiRateLimiter(double capacity, double refillRatePerSecond) {
        this.capacity = capacity;
        this.refillRatePerSecond = refillRatePerSecond;
    }

    private Bucket getOrCreateBucket(String clientId) {
        return buckets.computeIfAbsent(clientId, key -> {
            Bucket b = new Bucket();
            b.tokens = capacity;
            b.lastRefillNanos = System.nanoTime();
            return b;
        });
    }

    public boolean allow(String clientId) {
        Bucket bucket = getOrCreateBucket(clientId);
        bucket.lock.lock();
        try {
            long now = System.nanoTime();
            double elapsedSeconds = (now - bucket.lastRefillNanos) / 1_000_000_000.0;
            double refreshed = Math.min(capacity, bucket.tokens + elapsedSeconds * refillRatePerSecond);
            bucket.lastRefillNanos = now;

            if (refreshed >= 1) {
                bucket.tokens = refreshed - 1;
                return true;
            }
            bucket.tokens = refreshed;
            return false;
        } finally {
            bucket.lock.unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ApiRateLimiter limiter = new ApiRateLimiter(5, 1); // burst of 5, refill 1 per second
        Runnable[] tasks = new Runnable[8];
        Thread[] threads = new Thread[8];
        for (int i = 0; i < 8; i++) {
            final int requestId = i;
            threads[i] = new Thread(() -> {
                boolean allowed = limiter.allow("client-42");
                System.out.println("request " + requestId + " for client-42: "
                        + (allowed ? "processed" : "rejected, too many requests"));
            });
        }
        for (Thread t : threads) t.start();
        for (Thread t : threads) t.join();
    }
}

