import threading
import time

class ApiRateLimiter:
    def __init__(self, capacity, refill_rate_per_second):
        self.capacity = capacity
        self.refill_rate = refill_rate_per_second
        self.buckets = {}
        self.registry_lock = threading.Lock()

    def get_or_create_bucket(self, client_id):
        with self.registry_lock:
            if client_id not in self.buckets:
                self.buckets[client_id] = {
                    "tokens": float(self.capacity),
                    "last_refill": time.monotonic(),
                    "lock": threading.Lock(),
                }
            return self.buckets[client_id]

    def allow(self, client_id):
        bucket = self.get_or_create_bucket(client_id)
        with bucket["lock"]:
            now = time.monotonic()
            elapsed = now - bucket["last_refill"]
            refreshed = min(self.capacity, bucket["tokens"] + elapsed * self.refill_rate)
            bucket["last_refill"] = now

            if refreshed >= 1:
                bucket["tokens"] = refreshed - 1
                return True

            bucket["tokens"] = refreshed
            return False


def handle_request(limiter, client_id, request_id):
    if limiter.allow(client_id):
        print(f"request {request_id} for {client_id}: processed")
    else:
        print(f"request {request_id} for {client_id}: rejected, too many requests")


limiter = ApiRateLimiter(capacity=5, refill_rate_per_second=1)
threads = [
    threading.Thread(target=handle_request, args=(limiter, "client-42", i))
    for i in range(8)
]
for t in threads:
    t.start()
for t in threads:
    t.join()

