#include <iostream>
#include <string>
#include <unordered_map>
#include <memory>
#include <mutex>
#include <chrono>
#include <thread>
#include <vector>
#include <algorithm>
using namespace std;
using namespace std::chrono;

class ApiRateLimiter {
public:
    ApiRateLimiter(double capacity, double refillRatePerSecond)
        : capacity(capacity), refillRatePerSecond(refillRatePerSecond) {}

    bool allow(const string& clientId) {
        Bucket* bucket = getOrCreateBucket(clientId);
        lock_guard<mutex> guard(bucket->lock);
        auto now = steady_clock::now();
        double elapsedSeconds = duration_cast<duration<double>>(now - bucket->lastRefill).count();
        double refreshed = min(capacity, bucket->tokens + elapsedSeconds * refillRatePerSecond);
        bucket->lastRefill = now;

        if (refreshed >= 1) {
            bucket->tokens = refreshed - 1;
            return true;
        }
        bucket->tokens = refreshed;
        return false;
    }

private:
    struct Bucket {
        double tokens;
        steady_clock::time_point lastRefill;
        mutex lock;
    };

    double capacity;
    double refillRatePerSecond;
    unordered_map<string, unique_ptr<Bucket>> buckets;
    mutex registryLock;

    Bucket* getOrCreateBucket(const string& clientId) {
        lock_guard<mutex> guard(registryLock);
        auto it = buckets.find(clientId);
        if (it == buckets.end()) {
            auto bucket = make_unique<Bucket>();
            bucket->tokens = capacity;
            bucket->lastRefill = steady_clock::now();
            Bucket* ptr = bucket.get();
            buckets[clientId] = move(bucket);
            return ptr;
        }
        return it->second.get();
    }
};

int main() {
    ApiRateLimiter limiter(5, 1); // burst of 5, refill 1 per second
    vector<thread> threads;
    for (int i = 0; i < 8; i++) {
        threads.emplace_back([&limiter, i]() {
            bool allowed = limiter.allow("client-42");
            cout << "request " << i << " for client-42: "
                 << (allowed ? "processed" : "rejected, too many requests") << endl;
        });
    }
    for (auto& t : threads) t.join();
    return 0;
}
